export async function loadShard(name: ShardName): Promise<CatalogEntry[]> {
  const id = SHARD_NAME_TO_ID[name];
  if (!id) throw new Error(`Unknown catalog shard: ${name}`);
  if (Array.isArray(id)) {
    const loaded = await Promise.all(id.map(async (shardId) => {
      const shard = await import(`./data/shards/${shardId}.json`, { with: { type: "json" } });
      return shard.default as unknown as CatalogEntry[];
    }));
    return loaded.flat();
  }
  const loaded = await import(`./data/shards/${id}.json`, { with: { type: "json" } });
  return loaded.default as unknown as CatalogEntry[];
}
